commands.command:
P=/home/siegfriedneto/.claude/plugins/cache/siegard-generator/siegard/5.2.0
d(){ python3 -B $P/bin/spec.py --decide "$1" . | head -1; }
d domain/ingest-workspace/_context <<'JSON'
{"field": "strategic", "unstated": "The material does not say whether the ingest screen is where the business differs or a solved problem.", "decided": "supporting", "why": "The screen only carries a document to the knowledge base the business differs on, so it serves the core without being it."}
JSON
d contracts/ingest-workspace/ingest-screen <<'JSON'
{"field": "answers", "unstated": "The material does not say which boundary holds the notices and messages of the ingest screen.", "decided": "The ingest screen is a published api whose caller is the owner, and every notice or message that tells the owner what happened or was refused is an answer of it.", "why": "A notice changes what the owner learns, while a control label, a heading or a placeholder keeps the control doing what it did."}
JSON
d contracts/ingest-workspace/bff-ingestion <<'JSON'
{"field": "answers", "unstated": "The material does not say how much of the back end's answers the screen's own contract restates, since the ingestion contract already publishes them.", "decided": "The consumed contract states only how the screen sends each request and reads each answer, and the failures the client itself reports, never the fields the upstream publishes.", "why": "A field stated in both contracts is held twice with nothing to keep the two in agreement."}
JSON
d rules/ingest-workspace/connection-drop-is-an-unconflicting-envelope <<'JSON'
{"field": "statement", "unstated": "The material lists the codes that end in the error phase and says any other failure envelope that is not a conflict is silently polled, which includes codes the same screen lists as retryable.", "decided": "A failure envelope counts as a connection drop unless its status is 409 or 422 or its code is one of the three named, whatever else it carries.", "why": "The code treats the three named codes and the two statuses as the only exceptions, so the exceptions are what the rule names."}
JSON
cd .. && grep -n '' siegard-survey/adopt-fe-ingest/boundary.md | grep -E '^[0-9]+:- ' | cut -c1-100
